// ---------------------------------------------------------------------------

function slugify(name: string): string {
  const raw = name
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-|-$/g, "")
    .slice(0, 60);
  // DB constraint requires minimum 3 chars starting and ending with alphanumeric.
  if (raw.length < 3) return raw.padEnd(3, "1");
  return raw;
}

// DB constraint only accepts 6-digit hex (#rrggbb).
function isValidHex(value: string): boolean {
  return /^#[0-9A-Fa-f]{6}$/.test(value);
}

